          delay0_im <= adder2_im;
        end
      end
    end

  assign adder1_add_cast = {{3{gain63_re[15]}}, gain63_re};
  assign adder1_re = delay0_re + adder1_add_cast;
  assign adder1_add_cast_1 = {{3{gain63_im[15]}}, gain63_im};
  assign adder1_im = delay0_im + adder1_add_cast_1;

  always @(posedge clk or posedge reset)
    begin : unit_delay1_process
      if (reset == 1'b1) begin
        delay_1_re <= 19'sb0000000000000000000;
        delay_1_im <= 19'sb0000000000000000000;
      end
      else begin
        if (enb_1_6_0) begin
          delay_1_re <= adder1_re;
          delay_1_im <= adder1_im;
        end
      end
    end

  assign adder0_add_cast = {{3{gain63_re[15]}}, gain63_re};
  assign Discrete_FIR_Filter_out_re = delay_1_re + adder0_add_cast;
  assign adder0_add_cast_1 = {{3{gain63_im[15]}}, gain63_im};
  assign Discrete_FIR_Filter_out_im = delay_1_im + adder0_add_cast_1;

endmodule  // Discrete_FIR_Filter

